"""
One website in one tab, and the actions a model may take on it.

`SiteSession` owns the tab (and popups it opens) for one website. After every action it settles the page with
generic helpers that make no decisions: sign in with the run's credentials when a login form shows, accept only
the necessary cookies, pass "slide to unlock / not a robot" checks, close modal popups through their close button,
reload transient error pages and sign in again after a session timeout. What to open, search, read and enter is
left to the model through `TOOLS`.
"""
import asyncio
import contextvars
import os
import re
import time
from dataclasses import dataclass, field
from urllib.parse import urljoin, urlparse

from extract import FRAME_SECONDS, changes, locate, observe, select_options
from playwright.async_api import BrowserContext, Dialog, Page
from pydantic_ai import RunContext
from tracing import Trace

SETTLE_SECONDS = 45  # upper bound for waiting on a page and its helpers after one action
MAX_VIEW = 14000  # characters of a page shown at once; read_more pages through the rest
# A start waits on its tab while it loads: a slow site under load is still alive, and a new tab only queues behind
# the old request. But a tab can also hang for minutes in a context whose requests never complete while the same
# site opens at once in a fresh context (seen in sandbox runs). So an attempt without a usable page after RACE_AFTER
# gets a second tab in a fresh context next to it; the first usable page wins and the other tab is closed.
ATTEMPT_SECONDS = (45, 60, 90, 120)  # budgets of successive attempts (the last repeats)
START_SECONDS = float(os.environ.get("SESSION_START_SECONDS", "120"))  # no attempt runs longer than this
RACE_AFTER = 15  # an attempt without a usable page this long races a tab in a fresh context against its own
STUCK_SECONDS = 20  # a loaded page that answers no script call this long is dead: its tab is given up
PROBE_SECONDS = 5  # one check whether the page answers a script call
HELPER_SECONDS = 15  # one settle helper (sign-in, cookies, ...) on one page
GOTO_SECONDS = 30  # a navigation may take this long before the page is waited on in smaller steps
SLOW_PAGE = 10  # a navigation slower than this is traced
LOOK_SECONDS = 30  # one try to read a page that is still loading during a start
LOGIN_PATIENCE = 45  # a sign-in form still showing this soon after sending it is the post still pending
START_BACKOFF = (0, 10, 30)  # seconds between failed attempts (the last repeats); retries use a fresh context
START_MARGIN = 300  # by default a start keeps retrying until this long before the run's deadline
MIN_ATTEMPT = 15  # an attempt (or a racing tab) with less time than this is not begun
FRESH_AFTER = 1  # after this many failed attempts, each one runs in a fresh browser context (rules out the context)
DEADLINE: float | None = None  # the run's deadline (time.monotonic()); agent.solve sets it
_STARTING: contextvars.ContextVar = contextvars.ContextVar("starting", default=None)  # the session start() runs for
LOOP_VISITS = 3  # arriving on one page this often in a session gets the model a loop hint

# Closes modal <dialog>s and aria-modal popups through their own close button as soon as they open, and records
# what it closed. Links inside popups ("accept and continue") are never followed.
AUTO_CLOSE_JS = r"""
(() => {
  if (window.__arInit) return;
  window.__arInit = true;
  const CLOSE = /^(×|✕|✖|x|schließen|schliessen|close|dismiss|ausblenden|später|later|nicht jetzt|not now)$/i;
  const closed = (window.__arClosed = window.__arClosed || []);
  function closeButton(d) {
    for (const b of d.querySelectorAll('button,[role=button]')) {
      const name = (b.getAttribute('aria-label') || b.textContent || '').trim();
      if (CLOSE.test(name) || b.hasAttribute('data-close')) return b;
    }
    return null;
  }
  function check() {
    for (const d of document.querySelectorAll('dialog[open],[role=dialog][aria-modal=true],[role=alertdialog]')) {
      const modal = d.tagName !== 'DIALOG' || d.matches(':modal');
      if (!modal || d.dataset.arClosed) continue;
      const b = closeButton(d);
      if (!b) continue;
      d.dataset.arClosed = '1';
      closed.push((d.getAttribute('aria-label') || d.querySelector('h1,h2,h3')?.textContent || 'popup').trim());
      b.click();
      if (d.tagName === 'DIALOG' && d.open) d.close();
    }
  }
  const start = () => {
    check();
    new MutationObserver(check).observe(document.documentElement,
      {subtree: true, childList: true, attributes: true, attributeFilter: ['open', 'aria-modal', 'style', 'class']});
  };
  if (document.documentElement) start(); else document.addEventListener('DOMContentLoaded', start);
})();
"""

# "Slide to unlock" plus "I am not a robot" checks in any frame: drag the slider to its end, tick only boxes that
# are labelled as a robot check. Other checkboxes (terms, declarations) are left to the model.
HUMAN_CHECK_JS = r"""
() => {
  const ROBOT = /roboter|robot|mensch\b|human/i, SLIDE = /entsperr|unlock|zieh|slide|schieb/i;
  const labels = e => e.labels ? Array.from(e.labels).map(l => l.textContent) : [];
  const text = e => [e.getAttribute('aria-label') || '', ...labels(e)].join(' ');
  const done = [];
  for (const r of document.querySelectorAll('input[type=range]')) {
    const around = text(r) + ' ' + (r.parentElement ? r.parentElement.textContent : '');
    const max = r.max || '100';
    if (!SLIDE.test(around) || r.value === max || r.disabled) continue;
    r.value = max;
    r.dispatchEvent(new Event('input', {bubbles: true}));
    r.dispatchEvent(new Event('change', {bubbles: true}));
    done.push('unlock slider');
  }
  for (const c of document.querySelectorAll('input[type=checkbox]')) {
    if (c.checked || c.disabled || !ROBOT.test(text(c))) continue;
    c.click();
    done.push('robot check');
  }
  return done;
}
"""

ERROR_PAGE = re.compile(r"vorübergehend nicht verfügbar|temporarily unavailable|service unavailable|bad gateway|"
                        r"gateway time-?out|internal server error|bitte versuchen sie es (später )?erneut",
                        re.IGNORECASE)
COOKIE = re.compile(r"cookie", re.IGNORECASE)
COOKIE_ANSWER = re.compile(r"akzeptier|accept|zustimm|agree|ablehn|reject|erlaub|allow|bestätig|confirm|ok\b",
                           re.IGNORECASE)
COOKIE_MINIMAL = re.compile(r"notwendig|erforderlich|necessary|essential|nur technisch|ablehnen|reject|decline",
                            re.IGNORECASE)


def _budget(attempt: int) -> float:
    """Seconds start attempt `attempt` (from 1) may take."""
    return min(START_SECONDS, ATTEMPT_SECONDS[min(attempt, len(ATTEMPT_SECONDS)) - 1])


async def _close_quietly(page: Page) -> None:
    try:
        await asyncio.wait_for(page.close(), 10)
    except Exception:
        pass


async def _close_context(context: BrowserContext | None) -> None:
    if context is None:
        return
    try:
        await asyncio.wait_for(context.close(), 10)
    except Exception:
        pass


@dataclass
class SiteSession:
    """A website of the run (`siteId`, `url`, `credentials`) worked in its own tab."""

    site: dict
    context: BrowserContext
    trace: Trace
    pages: list[Page] = field(default_factory=list)
    events: list[str] = field(default_factory=list)  # what the helpers did since the model last looked
    view: str = ""
    lock: asyncio.Lock = field(default_factory=asyncio.Lock)
    stamp: int = 0
    logins: int = 0
    restarts: int = 0  # times the site was started again because its page stopped answering (reopen)
    seen: str = ""  # every view's text this session, to check notes against
    shown: tuple = ()  # (url, title, view) the model has now, so an unchanged page is not sent again
    base: tuple = ()  # the same for the latest view it got in full; changes are told against this one
    visits: dict[str, int] = field(default_factory=dict)  # page URL -> times the model arrived on it
    last_url: str = ""
    scripted: object = None  # the context the popup closer is installed in
    until: float | None = None  # a running start retries until then; may be moved while it runs
    ok: bool = False  # a start succeeded
    settled: asyncio.Event = field(default_factory=asyncio.Event)  # the latest start ended, either way
    login_at: tuple = ()  # (time.monotonic(), url) of the latest sign-in the helpers sent
    _start_owner: object = None  # set while start() runs; its own looks (any task under it) must not wait
    _old_context: object = None
    _adopted_by: object = None  # a start contender whose tab won: the session that took its tab over

    @property
    def name(self) -> str:
        return self.site["siteId"]

    @property
    def page(self) -> Page:
        open_pages = [p for p in self.pages if not p.is_closed()]
        self.pages = open_pages
        return open_pages[-1]

    def default_until(self) -> float:
        if DEADLINE is not None:
            return DEADLINE - START_MARGIN
        return time.monotonic() + _budget(1) + START_BACKOFF[0] + _budget(2)

    @property
    def starting(self) -> bool:
        return self._start_owner is not None

    async def start(self, attempts: int | None = None, until: float | None = None) -> str:
        """
        Open the site's start page in a new tab, signed in. One attempt waits on its tab while the page loads (its
        budget grows with the attempts, ATTEMPT_SECONDS); after RACE_AFTER without a usable page a second tab in a
        fresh context races it, and the first usable page wins. A tab ends early on the browser's error page, when
        it closes, or when its page stops answering (STUCK_SECONDS). Failed attempts are retried in a fresh
        context after a short backoff until `until` (default: START_MARGIN before the run's deadline; `self.until`
        may be moved while this runs) or `attempts` attempts.
        """
        if until is not None or self.until is None:
            self.until = until if until is not None else self.default_until()
        self._start_owner = _STARTING.set(self)
        self.ok = False
        self.settled.clear()
        if self._old_context is None:
            self._old_context = self.context  # the context the session was made with
        began = time.monotonic()
        tries = 0
        try:
            while True:
                tries += 1
                end = min(time.monotonic() + _budget(tries), self.until)
                own = (self.context, self.scripted)
                fresh = await self._fresh_context() if tries > FRESH_AFTER else None
                if fresh is not None:
                    self.context, self.scripted = fresh, None
                try:
                    winner, view = await self._race(end, began)
                except asyncio.CancelledError:
                    await self._close_pages()
                    self.context, self.scripted = own
                    await _close_context(fresh)
                    raise
                except Exception as error:
                    self.trace.event(self.name, "start_failed", attempt=tries,
                                     seconds=round(time.monotonic() - began, 1),
                                     error=f"{type(error).__name__}: {str(error)[:160]}")
                    await self._close_pages()
                    self.context, self.scripted = own  # the fresh context did not help: back
                    await _close_context(fresh)
                else:
                    if winner is not self:
                        await self._adopt(winner)
                        await _close_context(fresh)  # this attempt's own context lost the race
                    self.ok = True
                    self.trace.event(self.name, "start_ok", attempt=tries, seconds=round(time.monotonic() - began, 1),
                                     fresh_context=self.context is not self._old_context, raced=winner is not self)
                    return view
                if attempts is not None and tries >= attempts:
                    break
                wait = START_BACKOFF[min(tries, len(START_BACKOFF)) - 1]
                if time.monotonic() + wait + MIN_ATTEMPT > self.until:
                    break
                self.trace.event(self.name, "start_retry", after=wait, attempt=tries + 1)

"""
Efficiency tools for the browsing workers: common mechanical steps in one tool call instead of many model steps.

Each tool acts only on what the model points at and makes no decision of its own:

- `search(field_ref, query, submit_ref)`: types the model's query into the model's search field, submits, and lists
  the rows of the result list the site shows, following its next / load-more control until the list stops growing.
- `collect(list_ref)`: pages through the list or table the model points at (or the main list of the current page)
  and returns its rows once, without the repeats that "load more" and past-the-end pages produce.
- `extract(fields)`: one model call (thinking off) over the current view that reports each asked field with the
  exact quote it came from; a field whose quote is not in the view is dropped.
- Deterministic normalisers for locale-tagged numbers, prices per unit and day/month-ambiguous dates: a reading that
  the text does not settle returns every reading instead of a guess.

Controls and lists are found through refs and roles, never through site-specific labels, URLs or values.
"""
import re
import time
from dataclasses import dataclass, field
from datetime import date
from decimal import Decimal
from urllib.parse import unquote_plus

from pydantic import BaseModel, Field
from pydantic_ai import Agent, RunContext

import llm
from browser_tools import Deps, SiteSession, _click
from evidence import ParseError, number_format, parse_number
from extract import locate

MAX_PAGES = 25     # list pages followed per call
MAX_ROWS = 200     # rows returned per call
ROW_CHARS = 300    # characters of one row shown

_REF = re.compile(r"\[e\d+ ")

# Words that mark a control which shows more of a list, in any language the sites use. Matched against the control's
# own name only, so a "next" inside a record title does not count.
NEXT_WORDS = (r"(weiter|mehr|nächste|naechste|next|more|load more|show more|zeige|folgende|vorwärts|vorwaerts|"
              r"›|»|>|→)")
STOP_WORDS = (r"(zurück|zurueck|vorherige|previous|prev|back|‹|«|<|←|erste|first|letzte|last|neu laden|reload|"
              r"aktualisier|refresh|↻|⟳|⌂|öffnen|open|download|herunterladen)")

TOO_MANY = re.compile(r"[^.\n]*(zu viele|too many|mehr als \d+|more than \d+|einschränken|einschraenken|eingrenzen|"
                      r"verfeinern|narrow|refine|zu allgemein|too broad|maximal \d+|at most \d+|limit)[^.\n]*",
                      re.IGNORECASE)
NO_HITS = re.compile(r"[^.\n]*(keine (treffer|ergebnisse|einträge|eintraege|daten|datensätze|datensaetze)|"
                     r"nichts gefunden|no (results|hits|matches|entries|records|items|data)|nothing found|not found|"
                     r"\b0 (treffer|ergebnisse|results|hits))[^.\n]*", re.IGNORECASE)

# Rows of a list: a container's repeated children. `arg` is [element or null, path or null]: a ref's element climbs
# to the repeating container around it; a remembered path finds the container again after a page change; without
# either, the page's main list (most rows with links and text, outside navigation) is chosen. Each row's visible
# text (tooltips, image labels and titles included, hidden text excluded) and its links with their refs come back.
ROWS_JS = r"""
([start, path]) => {
  const ZW = /[​‌‍⁠﻿­]/g;
  const clean = s => (s || '').replace(ZW, '').replace(/\s+/g, ' ').trim();
  const NAV = 'nav,header,footer,[role=navigation],[role=menu],[role=menubar],[role=tablist],select,datalist';
  function hidden(el) {
    if (el.hidden || el.getAttribute('aria-hidden') === 'true') return true;
    const cs = getComputedStyle(el);
    return cs.display === 'none' || cs.visibility === 'hidden';
  }
  function text(node) {
    let out = '';
    for (const c of node.childNodes) {
      if (c.nodeType === 3) { out += c.nodeValue.replace(ZW, ''); continue; }
      if (c.nodeType !== 1) continue;
      const tag = c.tagName;
      if (tag === 'SCRIPT' || tag === 'STYLE' || tag === 'TEMPLATE') continue;
      if (c.getAttribute('role') === 'tooltip') {
        if (c.getAttribute('aria-hidden') !== 'true') out += ' (tooltip: ' + clean(c.textContent) + ') ';
        continue;
      }
      if (hidden(c)) continue;
      if (tag === 'CANVAS' || tag === 'IMG' || tag === 'svg' || tag === 'SVG' || c.getAttribute('role') === 'img') {
        const l = clean(c.getAttribute('aria-label') || c.getAttribute('alt') || c.getAttribute('title'));
        if (l) out += ' [img: ' + l + '] ';
        continue;
      }
      if (tag === 'SELECT') {
        const sel = Array.from(c.options).filter(o => o.selected).map(o => clean(o.textContent)).join(', ');
        out += ' [' + sel + '] ';
        continue;
      }
      if (tag === 'INPUT') {
        if (c.type === 'checkbox' || c.type === 'radio') out += c.checked ? ' [x] ' : ' [ ] ';
        else if (c.type !== 'hidden' && c.type !== 'password' && c.value) out += ' ' + clean(c.value) + ' ';
        continue;
      }
      const cs = getComputedStyle(c);
      const cell = cs.display === 'table-cell' || tag === 'TD' || tag === 'TH';
      const block = /^(block|flex|grid|table|table-row|list-item|flow-root)$/.test(cs.display);
      out += text(c);
      if (tag === 'TIME' && c.getAttribute('datetime')) out += ' (datetime=' + c.getAttribute('datetime') + ')';
      const title = c.getAttribute('title');
      if (title && !clean(c.textContent).includes(clean(title))) out += ' (title: ' + clean(title) + ')';
      if (cell) out += ' | '; else if (block) out += ' ; ';
    }
    return out;
  }
  function sig(el) {
    return el.tagName + '|' + (el.className && el.className.baseVal === undefined ? el.className : '');
  }
  function rowsOf(container) {
    let kids = Array.from(container.children).filter(k => !hidden(k));
    if (container.tagName === 'TABLE') {
      kids = Array.from(container.querySelectorAll(':scope > tbody > tr, :scope > tr')).filter(k => !hidden(k));
    }
    kids = kids.filter(k => !(k.tagName === 'TR' && k.querySelectorAll('td').length === 0
                              && k.querySelectorAll('th').length));
    kids = kids.filter(k => !['THEAD', 'TFOOT', 'CAPTION', 'COLGROUP', 'SCRIPT', 'STYLE'].includes(k.tagName));
    // a list element (table, ul, role=list) is a list even with a single row (one record per page); any other
    // container needs at least two repeated children
    const least = listy(container) ? 1 : 2;
    if (kids.length < least) return [];
    const counts = {};
    for (const k of kids) counts[sig(k)] = (counts[sig(k)] || 0) + 1;
    const best = Object.keys(counts).sort((a, b) => counts[b] - counts[a])[0];
    return counts[best] >= least ? kids.filter(k => sig(k) === best) : [];
  }
  function listy(el) {
    const role = el.getAttribute('role');
    return ['TABLE', 'TBODY', 'UL', 'OL'].includes(el.tagName) || ['list', 'table', 'grid'].includes(role);
  }
  function score(container) {
    const rows = rowsOf(container);
    if (!rows.length || container.closest(NAV)) return 0;
    let chars = 0, links = 0;
    for (const r of rows) {
      const t = clean(r.textContent);
      chars += Math.min(t.length, 200);
      if (r.querySelector('a[href],button,[role=link],[role=button]')) links += 1;
    }
    if (chars / rows.length < 6) return 0;
    return (rows.length + links) * (chars / rows.length) * (listy(container) ? 1.5 : 1);
  }
  function pathOf(el) {
    const parts = [];
    for (let e = el; e && e !== document.body; e = e.parentElement) {
      let p = e.tagName.toLowerCase();
      if (e.id) { parts.unshift(p + '#' + CSS.escape(e.id)); break; }
      const same = Array.from(e.parentElement ? e.parentElement.children : []).filter(s => s.tagName === e.tagName);
      if (same.length > 1) p += ':nth-of-type(' + (same.indexOf(e) + 1) + ')';
      parts.unshift(p);
    }
    return parts.join(' > ');
  }
  let container = null, how = '';
  if (start) {
    for (let e = start; e && e !== document.body; e = e.parentElement) {
      if (e.tagName === 'TABLE' && rowsOf(e).length) { container = e; how = 'table at ref'; break; }
      const parent = e.parentElement;
      if (parent && rowsOf(parent).includes(e)) { container = parent; how = 'list around ref'; break; }
      if (rowsOf(e).length && score(e) > 0) { container = e; how = 'list at ref'; break; }
    }
  }
  if (!container && path) {  // the list read before: still marked (rows were loaded into it) or at the same path
    const marked = document.querySelector('[data-ar-list]');
    if (marked && rowsOf(marked).length) { container = marked; how = 'same list'; }
    else try {
      const e = document.querySelector(path);
      if (e && rowsOf(e).length) { container = e; how = 'same list'; }
    } catch (err) {}
  }
  if (!container) {
    let best = 0;
    const LISTS = 'table,tbody,ul,ol,div,section,[role=list],[role=table],[role=grid]';
    for (const e of document.body.querySelectorAll(LISTS)) {
      if (e.closest('[data-ar-list-skip]')) continue;
      const s = score(e);
      if (s > best) { best = s; container = e; how = 'main list of the page'; }
    }
  }
  if (!container) return {rows: [], path: '', how: ''};
  document.querySelectorAll('[data-ar-list]').forEach(e => e.removeAttribute('data-ar-list'));
  container.setAttribute('data-ar-list', '1');
  const rows = rowsOf(container).map(r => {
    const links = [];
    for (const a of r.querySelectorAll('a[href],button,[role=link],[role=button],summary')) {
      if (hidden(a)) continue;
      links.push({ref: a.getAttribute('data-ar') || '',
                  text: clean(a.innerText || a.textContent || a.getAttribute('aria-label')),
                  href: a.tagName === 'A' ? a.getAttribute('href') : ''});
    }
    const t = clean(text(r)).replace(/( [;|] )+/g, m => m.includes('|') ? ' | ' : ' ; ')
      .replace(/^( [;|] )+/, '').replace(/( ?[|;])+$/, '');
    return {text: t, links};
  });
  return {rows, path: pathOf(container), how, tag: container.tagName.toLowerCase()};
}
"""

# Controls that show more of a list, by their own name (button, link or anything clickable), enabled only: the ones
# inside or after the container come first, so a page's unrelated "next" (a wizard step) is not taken by mistake.
NEXT_JS = r"""
([path, nextWords, stopWords]) => {
  const NEXT = new RegExp(nextWords, 'i'), STOP = new RegExp(stopWords, 'i');
  const clean = s => (s || '').replace(/\s+/g, ' ').trim();
  let container = document.querySelector('[data-ar-list]');
  try { if (!container && path) container = document.querySelector(path); } catch (e) {}
  const found = [];
  const CLICKABLE = 'a[href],button,[role=button],[role=link],input[type=submit],input[type=button]';
  for (const el of document.querySelectorAll(CLICKABLE)) {
    if (el.disabled || el.getAttribute('aria-disabled') === 'true' || !el.getAttribute('data-ar')) continue;
    const cs = getComputedStyle(el);
    if (cs.display === 'none' || cs.visibility === 'hidden') continue;
    const name = clean(el.getAttribute('aria-label') || el.innerText || el.value || el.textContent || el.title);
    if (!name || name.length > 40 || !NEXT.test(name) || STOP.test(name)) continue;
    let where = 2;  // a control before a known list is never its pagination (toolbars, imitation browser chrome)
    if (container) {
      if (container.contains(el)) where = 0;
      else if (container.compareDocumentPosition(el) & Node.DOCUMENT_POSITION_FOLLOWING) where = 1;
      if (where === 2) continue;
    } else if (el.closest('nav,header,footer,[role=navigation],[role=menubar]')) {
      continue;  // without a known list, site navigation is not pagination (a pagination <nav> after the list is)
    }
    found.push({ref: el.getAttribute('data-ar'), name, where});
  }
  found.sort((a, b) => a.where - b.where);
  return found;
}
"""


@dataclass
class Row:
    text: str
    links: list[dict] = field(default_factory=list)
    current: bool = True  # on the page shown now, so its refs resolve


