                sub = await asyncio.wait_for(frame.evaluate(WALK_JS, [next_id, stamp]), WALK_SECONDS)
            except Exception:
                continue
            next_id = sub["next"]
            parts.append(f"[frame {frame.url}]\n{sub['text']}\n[/frame]")
    return "\n".join(parts)


